@property
def in_transaction(self):
    """Check if this database is in a transactional context."""
    if not hasattr(self.local, "tx"):
        return False
    return len(self.local.tx) > 0

@contextmanager
def _autocommit(self):
    """Run a statement and commit it, unless an explicit transaction is active.

    SQLAlchemy 2.0 no longer commits implicitly, so writes made outside of
    ``begin()`` are committed here, the same way SQLAlchemy 1.4 did.
    Yields the connection to execute against.
    """
    conn = self.executable
    if self.in_transaction or getattr(self.local, "autocommit", False):
        # Either the caller manages the transaction, or we are already
        # inside an outer statement block that will commit.
        yield conn
        return
    self.local.autocommit = True
    try:
        yield conn
        conn.commit()
    except BaseException:
        conn.rollback()
        raise
    finally:
        self.local.autocommit = False

